/** The icon of each attraction type (AM_ATTRACTION_TYPES), for the map, the routes and the planner. */
const AM_PLACE_TYPE_ICONS = [
    'castel-palat' => 'castle', 'muzeu' => 'museum', 'monument' => 'columns', 'biserica-manastire' => 'church',
    'parc-gradina' => 'park', 'piata-centru-vechi' => 'city', 'cladire-istorica' => 'house', 'punct-panoramic' => 'binoculars',
    'lac-natura' => 'waves', 'teatru-opera' => 'theatre',
];

/** The icons the map, route and planner pages use (their sprite): the types above plus the planner's own. */
const AM_PLACE_ICON_KEYS = ['castle', 'museum', 'columns', 'church', 'park', 'city', 'house', 'binoculars', 'waves', 'theatre', 'mountains',
    'hammer', 'evergreen', 'palette', 'map', 'pin', 'clock', 'moon', 'bed', 'fork', 'coffee', 'armchair', 'walk', 'shopping', 'group', 'baby',
    'heart', 'ticket', 'sparkle', 'star', 'hike', 'tree'];

/** An attraction type's icon key (by slug), 'pin' when the type is unknown. */
function am_place_icon(?string $typeSlug): string
{
    return AM_PLACE_TYPE_ICONS[$typeSlug ?? ''] ?? 'pin';
}

/** The default icon of each product type, when the operator chose none. */
const AM_PRODUCT_TYPE_ICONS = ['access' => 'ticket', 'experience' => 'lightning', 'package' => 'gift'];

/** A stored value as a known key, or null (no icon, an emoji saved before, anything unknown). */
function am_product_icon($value): ?string
{
    return is_string($value) && isset(AM_PRODUCT_ICONS[$value]) ? $value : null;
}

/** The product's own icon, or its type's. */
function am_product_icon_or_type($value, ?string $type): string
{
    return am_product_icon($value) ?? (AM_PRODUCT_TYPE_ICONS[$type ?? ''] ?? 'ticket');
}

/**
 * The <symbol>s for the given keys (all of them with null), in a hidden <svg>. Unknown keys are skipped; the type
 * defaults are always there, so a product without its own icon can still show one.
 */
function am_product_icon_sprite(?array $keys = null): string
{
    $keys = $keys === null ? array_keys(AM_PRODUCT_ICONS) : array_values(array_unique(array_merge(array_values(AM_PRODUCT_TYPE_ICONS), $keys)));
    $out = '';
    foreach ($keys as $key) {
        if (is_string($key) && isset(AM_PRODUCT_ICONS[$key])) {
            $out .= '<symbol id="i-pi-' . $key . '" viewBox="0 0 256 256"><g fill="currentColor">' . AM_PRODUCT_ICONS[$key][2] . '</g></symbol>';
        }
    }
    return '<svg width="0" height="0" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true" focusable="false">' . $out . '</svg>';
}

/** One icon, for a page that printed its sprite. */
function am_product_icon_svg(string $key, string $class = 'ic'): string
{
    return '<svg class="' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') . '" aria-hidden="true" focusable="false"><use href="#i-pi-' . htmlspecialchars($key, ENT_QUOTES, 'UTF-8') . '"/></svg>';
}

/** For the operator's editor (#v2-data): [[key, label, group]], in the order above. */
function am_product_icon_list(): array
{
    $out = [];
    foreach (AM_PRODUCT_ICONS as $key => [$label, $group]) {
        $out[] = [$key, $label, $group];
    }
    return $out;
}
